// Student input vector (FEATURE_VERSION). Every dimension is named (studentNames); docs/distill-features.md lists them
// (generated by `node distill/cli.mjs features-doc`). Three blocks:
//   1. the seat's own block from advisor/features-table.mjs tableSelf (one implementation of the unit/bond encoding):
//      round, economy, current boss stats, board 10 / hand 6 / shop 5 unit slots by attribute, bonds (count, tier,
//      active, layers, pace vs the natural curve, projected R13 layers);
//   2. boss identity: one-hot R14 boss; one-hot hidden boss only once it is revealed (R15), as in the advisor's rollouts;
//   3. the three teammates (seat order after this seat) from the PUBLIC view only (m.publicView().players — what a live
//      client sees too): present, alive, LP, level, deployed count, total / main-line layers, per-bond count and layers.
//      No teammate funds, hand or shop (the simulator knows them, a real client does not).
import { tableNames, tableSelf } from '../advisor/features-table.mjs';
import { data } from '../eval/engine.mjs';

export const FEATURE_VERSION = 1;
const MATES = 3, MATE_SCALARS = ['present', 'alive', 'lp', 'level', 'board', 'layersTotal', 'mainLayers'];
let cache = null;
export function studentNames(gd) {
  if (cache) return cache;
  const t = tableNames(gd), bosses = Object.keys(data.bosses), bonds = gd.bondIds;
  const names = [...t.names.slice(0, t.selfN), ...bosses.map(b => `boss.${b}`), ...bosses.map(b => `hidden.${b}`)];
  for (let k = 1; k <= MATES; k++) names.push(...MATE_SCALARS.map(n => `mate+${k}.${n}`), ...bonds.flatMap(b => [`mate+${k}.${b}.count`, `mate+${k}.${b}.layers`]));
  cache = { names, bosses, bonds, selfN: t.selfN, version: FEATURE_VERSION };
  return cache;
}
export function studentFeatures(m, ps) {
  const { names, bosses, bonds } = studentNames(m.gd), v = tableSelf(m, ps);
  for (const b of bosses) v.push(m.bossId === b ? 1 : 0);
  for (const b of bosses) v.push(m.round >= m.gd.hiddenRound && m.hiddenBossId === b ? 1 : 0);
  const pub = m.publicView().players, me = pub.findIndex(p => p.playerId === ps.playerId);
  if (me < 0) throw Error(`studentFeatures: ${ps.playerId} not in the public view`);
  for (let k = 1; k <= MATES; k++) {
    const q = pub.length > k ? pub[(me + k) % pub.length] : null;
    if (!q) { v.push(...new Array(MATE_SCALARS.length + 2 * bonds.length).fill(0)); continue; }
    const by = new Map((q.bonds || []).filter(b => !b.off).map(b => [b.bondId, b]));
    const layers = [...by.values()].map(b => b.layers || 0);
    v.push(1, q.alive ? 1 : 0, q.lp, q.shopLevel, q.boardCount, layers.reduce((s, x) => s + x, 0), Math.max(0, ...layers));
    for (const b of bonds) v.push(by.get(b)?.count || 0, by.get(b)?.layers || 0);
  }
  if (v.length !== names.length) throw Error(`student features ${v.length} != ${names.length}`);
  return v.map(x => Number.isFinite(x) ? x : 0);
}
// The lines (core bonds with a guide recipe) the line head chooses from, in engine bond order.
export function lineIds(gd, spec) { return gd.bondIds.filter(b => spec.recipes[b]); }
